const $=id=>document.getElementById(id),names=['国库','民心','军备','朝局'];
let game=null,busy=false,modal=null,returnFocus=null,orders=[],eventChoice=-1,trigChoice=-1,mode='ai',decree='',policy=-1,filter='全部',selected=null,chats={},pendingRequest=null,privyRelease=0;
let portraits={};
