const aiReady=()=>!!game&&(game.authRequired?game.aiVerified:game.aiConfigured);
function provinceStatus(p){if(p.garrison<=28)return '兵弱';if(p.popular<=30)return '民变';if(p.develop<=42&&p.popular<=42)return '旱灾';if(p.garrison>=58&&p.develop<=45)return '边警';if(p.develop<=30)return '凋敝';if(p.popular>=66&&p.develop>=62)return '繁荣';if(p.popular>=55&&p.develop>=55)return '富庶';return '平稳'}

const el=(tag,value='',cls='')=>{const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e};
const button=(label,fn,cls='')=>{const b=el('button',label,cls);b.type='button';b.onclick=()=>{if(!busy)fn()};return b};
const state=()=>game.state;
