const nodeRevealed=n=>!n.hidden||(n.reveal&&((n.reveal.tech&&(state().tech.unlocked||[]).includes(n.reveal.tech))||(n.reveal.civic&&(state().civic.unlocked||[]).includes(n.reveal.civic))||(n.reveal.flag&&(state().flags||[]).includes(n.reveal.flag))));
