 const subtitles={army:'金戈铁马 · 整军经武',craft:'格物利民 · 经略山河',court:'九重宫阙 · 共议天下'};
 const hero=el('section','','detail-hero');
 const img=document.createElement('img');img.src='/scenes/'+kind+'.png';img.alt={army:'明军列阵于边关城下',craft:'工匠与水乡市镇',court:'明代宫廷与朝臣'}[kind];img.className='detail-scene';if(body.dataset.armyId){img.src=game.armyCatalog?.armies[body.dataset.armyId]?.image||img.src;img.alt=title.split(' · ')[0]+'军阵示意'}
 const text=el('div','','detail-heading');text.append(el('small',subtitles[kind]),el('h2',title.split(' · ')[0]),el('p',title.includes(' · ')?title.split(' · ').slice(1).join(' · '):'阅览档案 · 运筹帷幄'));
 const person=[...(state().ministers||[]),...(state().rivals||[])].find(p=>title.startsWith(p.name+' · '));
