function buildArmies(b,id=null){const armies=(state().armies||[]).filter(a=>!id||a.province===id);if(!armies.length){b.append(el('p','暂无驻军记录。'));return}const grid=el('div','','army-grid');for(const a of armies){const card=el('section','','army-card military-card');const art=document.createElement('img');art.src=game.armyCatalog?.armies[a.id]?.image||'/scenes/army.png';art.alt=a.name+'军阵示意';art.className='card-scene';art.loading='lazy';card.append(art);card.append(el('small',a.unitType||'未分类'),el('h3',a.name),el('p',(province(a.province)?.name||a.province)+' · 将领 '+personName(a.commander)),metrics([['兵力',Number(a.men).toLocaleString('zh-CN')+' 人'],['士气',a.morale+'/100'],['训练',a.training+'/100'],['装备',a.equipment+'/100']]));const cmdr=el('div','','row');const sel=select([['','指派将领'],...state().ministers.filter(m=>m.alive).map(m=>[m.id,m.name+'（兵'+m.ability.military+'）'])]);cmdr.append(field('将领',sel),button('任命',()=>{if(sel.value)armyAction({action:'appoint',armyId:a.id,ministerId:sel.value})}));if(a.commander)cmdr.append(button('解职',()=>armyAction({action:'dismiss',armyId:a.id})));const roster=armyComposition(a.men,visibleComposition(game.armyCatalog?.armies[a.id]?.composition));const tags=el('div','','unit-tags');for(const row of roster)tags.append(el('span',game.armyCatalog.units[row.unitId].name+' '+row.percent+'%'));card.append(tags,button('查看兵种 · '+roster.length+' 类',()=>openModal(a.name+' · 兵种编制',body=>buildArmyDetail(body,a.id)),'army-detail-button'),cmdr);grid.append(card)}b.append(grid)}

