function requestId(){
 if(typeof crypto.randomUUID==='function')return crypto.randomUUID();
 const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;
 const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return [hex.slice(0,8),hex.slice(8,12),hex.slice(12,16),hex.slice(16,20),hex.slice(20)].join('-');
}
function envelope(action){return {...action,gameId:state().id,revision:state().revision,requestId:requestId()}}
async function execute(){if(busy||!pendingRequest)return;busy=true;synchronize();const request=pendingRequest;setBusy(request.kind);let report=false;try{const response=await api(request.url,request.body);game=response;pendingRequest=null;if(request.kind==='turn'){orders=[];eventChoice=-1;trigChoice=-1;decree='';policy=-1;privyRelease=0;report=true}if(request.kind==='chat'){const history=chats[request.body.ministerId]||(chats[request.body.ministerId]=[]);history.push({who:'me',text:request.body.message},{who:'them',text:response.reply||'此问已处理，回复未由服务器重放。'});}render();if(state().ending){$('overlay').hidden=true;modal=null;document.body.classList.remove('modal-open')}else refreshModal();say('已处理，进度已保存。')}catch(e){if(e.status>=400&&e.status<500){pendingRequest=null;if(e.status===409){try{game=await api('/api/game');render();refreshModal()}catch{say('存档刷新失败，请重新读取存档。',true)}}}if(e.status===401){token=null;localStorage.removeItem('ming-token');game=null;$('overlay').hidden=true;modal=null;showAuth('登录已过期，请重新登录。')}else say(e.message,true)}finally{busy=false;synchronize();if(report&&game&&!state().ending)openModal('时局汇总 · '+reignOf(state().turn),buildReport)}}
function mutate(url,action,kind){if(busy)return;if(pendingRequest){say('有未确认请求，请先重试原请求或重新读取存档。',true);return}try{pendingRequest={url,body:envelope(action),kind};execute()}catch(e){pendingRequest=null;say('无法提交操作：'+e.message,true)}}
function submitTurn(action){if(!pendingRequest)closeModal();mutate('/api/turn',{...action,mode,orders:structuredClone(orders),eventChoice,trigChoice,privyRelease},'turn')}
function officeAction(action){mutate('/api/office',action,'office')}
function armyAction(action){mutate('/api/army',action,'army')}
function rivalAction(action){mutate('/api/rival',action,'rival')}
function examAction(action){mutate('/api/exam',action,'exam')}
function sendChat(id,message){if(busy||pendingRequest){say('请先处理当前请求，再发送问话。',true);return}if(!aiReady()){say('请先配置并测试你自己的 AI 模型。',true);return}const text=(message||'').trim();if(!text){say('请输入问话。',true);return}const history=chats[id]||(chats[id]=[]);refreshModal();mutate('/api/chat',{ministerId:id,message:text},'chat')}
async function load(){if(busy)return;busy=true;synchronize();try{game=await api('/api/game');pendingRequest=null;hideAuth();render();refreshModal();say('存档已读取。');if(game.authRequired&&!game.aiVerified)openAiConfig();}catch(e){if(e.status===401){token=null;localStorage.removeItem('ming-token');game=null;showAuth('请登录或注册后继续。')}else{say('无法读取存档：'+e.message,true);$('reload').hidden=false}}finally{busy=false;synchronize();if(!game)$('reload').hidden=false}}
function showAuth(msg=''){$('auth-overlay').hidden=false;$('auth-msg').textContent=msg;$('auth-user').focus()}
function hideAuth(){$('auth-overlay').hidden=true}
async function auth(mode){const username=$('auth-user').value.trim(),password=$('auth-pass').value;if(!username||!password){$('auth-msg').textContent='请填写用户名和密码。';return}try{const resp=await api('/api/'+mode,{username,password});token=resp.token;localStorage.setItem('ming-token',token);hideAuth();await load()}catch(e){$('auth-msg').textContent=e.message}}
function logout(){token=null;localStorage.removeItem('ming-token');game=null;showAuth('已退出登录。')}
const aiCfgKey='ming-aiconfig';
const readAiCfg=()=>{try{return JSON.parse(localStorage.getItem(aiCfgKey)||'{}')}catch{return{}}};
const writeAiCfg=c=>localStorage.setItem(aiCfgKey,JSON.stringify(c));
function openAiConfig(){const c=readAiCfg();$('aiconfig-key').value=c.apiKey||'';$('aiconfig-model').value=c.model||(game?.aiModel||'deepseek-v4-pro');$('aiconfig-base').value=c.baseUrl||'';$('aiconfig-msg').textContent=game?.aiVerified?'AI 已连通验证，可正常游玩。':(game?.authRequired?'请配置你自己的 AI 模型，通过连通性测试后方可游玩。':'');$('aiconfig-overlay').hidden=false;$('aiconfig-key').focus()}
function closeAiConfig(){$('aiconfig-overlay').hidden=true}
function openHelp(){$('help-overlay').hidden=false;$('help-close').focus()}
function closeHelp(){$('help-overlay').hidden=true}
async function testAiConfig(){const c={apiKey:$('aiconfig-key').value.trim(),model:$('aiconfig-model').value.trim(),baseUrl:$('aiconfig-base').value.trim()};if(!c.apiKey){$('aiconfig-msg').textContent='请填写 API Key。';return}writeAiCfg(c);$('aiconfig-msg').textContent='正在测试连通……';try{const r=await api('/api/aitest',c);if(r.ok){game=await api('/api/game');render();$('aiconfig-msg').textContent='连通成功，已生效。';setTimeout(closeAiConfig,600)}else{$('aiconfig-msg').textContent=r.error||'连通失败。'}}catch(e){$('aiconfig-msg').textContent=e.message}}
function reset(){if(!game||busy)return;if(!confirm('确定结束当前一局、清除本局进度并重新登基？'))return;pendingRequest=null;chats={};orders=[];eventChoice=-1;trigChoice=-1;decree='';policy=-1;mutate('/api/reset',{},'reset')}
$('btn-turn').onclick=()=>game&&!state().ending&&openModal('下旨推演 · '+reignOf(state().turn),buildTurn);
$('btn-court').onclick=()=>game&&openModal('朝堂 · 大臣',buildCourt);$('btn-exam').onclick=()=>game&&openModal('科举 · 殿试取士',buildExam);$('btn-counsel').onclick=()=>game&&openModal('意见册 · 群臣进言',buildCounsel);$('btn-tree').onclick=()=>game&&openModal('科技 · 市政',buildTrees);$('btn-armies').onclick=()=>game&&openModal('兵部 · 军队名册',buildArmies);$('btn-rivals').onclick=()=>game&&openModal('敌情 · 对立角色',buildRivals);$('btn-report').onclick=()=>game&&openModal('时局汇总 · '+reignOf(state().turn),buildReport);
$('close').onclick=closeModal;$('overlay').onclick=e=>{if(e.target===$('overlay'))closeModal()};$('modal-retry').onclick=execute;$('modal-reload').onclick=load;$('retry').onclick=execute;$('reload').onclick=load;$('reset').onclick=reset;
$('auth-login').onclick=()=>auth('login');$('auth-signup').onclick=()=>auth('signup');$('auth-pass').addEventListener('keydown',e=>{if(e.key==='Enter')auth('login')});
$('auth-ai').onclick=openAiConfig;$('aiconfig-save').onclick=testAiConfig;$('aiconfig-close').onclick=closeAiConfig;$('aiconfig-overlay').onclick=e=>{if(e.target.id==='aiconfig-overlay')closeAiConfig()};$('auth-help').onclick=openHelp;$('help-close').onclick=closeHelp;$('help-overlay').onclick=e=>{if(e.target.id==='help-overlay')closeHelp()};$('btn-ai').onclick=openAiConfig;$('logout').onclick=()=>{if(confirm('确定退出登录？'))logout()};
function trapFocus(container,e){const all=[...container.querySelectorAll('button,input,select,textarea,a')].filter(n=>!n.disabled&&n.offsetParent!==null);if(!all.length)return;const first=all[0],last=all.at(-1);if(!container.contains(document.activeElement)){e.preventDefault();first.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
document.addEventListener('keydown',e=>{const top=['help-overlay','aiconfig-overlay','auth-overlay','overlay'].find(id=>!$(id).hidden);if(!top||busy)return;if(e.key==='Escape'){e.preventDefault();if(top==='help-overlay')closeHelp();else if(top==='aiconfig-overlay')closeAiConfig();else if(top==='overlay')closeModal();return}if(e.key==='Tab')trapFocus($(top),e)});
